import { describe, it, expect } from "vitest";
import { createArcRotateCamera, createFreeCamera, getViewMatrix, enableOrthographicCamera } from "@babylonjs/lite";
import { labelPosition } from "./label-position";

function canvas(w: number, h: number, cw = w, ch = h) {
