    });
    it("floating origin matches absolute", () => {
        const FAR = 4_637_862.01;
        const abs = createFreeCamera({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 10 });
        const fo = createFreeCamera({ x: FAR, y: -FAR, z: FAR }, { x: FAR, y: -FAR, z: FAR + 10 });
        fo._useFloatingOrigin = true;
        const c = canvas(800, 600);
        const a = labelPosition(abs, c, { x: 0, y: 0, z: 10 });
        const b = labelPosition(fo, c, { x: FAR, y: -FAR, z: FAR + 10 });
