        expect(b.visible).toBe(true);
        expect(labelPosition(fo, c, { x: FAR, y: -FAR, z: FAR - 10 }).visible).toBe(false);
    });
    it("ortho", () => {
        const cam = createFreeCamera({ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 10 });
        enableOrthographicCamera(cam, { halfHeight: 5 });
        const c = canvas(800, 600);
        console.log("ortho behind", labelPosition(cam, c, { x: 0, y: 0, z: -5 }), "ortho front", labelPosition(cam, c, { x: 0, y: 0, z: 20 }));
    });
});
